function price(base, qty, vip = false) {
	if (qty <= 0) throw new Error("qty");
	let total = base * qty;
	if (qty >= 10) total *= .9;
	if (vip) total *= .8;
	return Math.round(total * 100) / 100;
};
function format(n) {
	return n.toFixed(2) + " Kč";
}

